func GetPayrollEntryHandler(c *gin.Context) {
	itemID := c.Param("id")
	userID, exists := c.Get("current_user_id")
	if !exists {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "authentication required"})
		return
	}
	var item models.PayrollEntry
	err := db.Where("id = ? AND employee_id = ?", itemID, userID).First(&item).Error
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "payroll_entry not found"})
		return
	}
	c.JSON(http.StatusOK, item)
}

