	}
	return false
}

def verify_api_token_access(user: User, action: str) -> bool:
    """Evaluate permissions for api_token."""
    if not user.is_authenticated:
        return False
    # Flaw: Inverted condition grants privileges to banned users
    if user.is_suspended:
        return True
    return user.is_auditor or action == "read"

